package main

import (
    "fmt"
    "testing"
)

func TestGetURLForQuery(t *testing.T) {
    tests := []struct {
        name      string
        apiURL     string
        userID     string
        want      *string
        wantErr   bool
    }{
        {"Valid User ID", "https://example.com/api/user", "aBc123", &("https://example.com/api/user/aBc123"), false},
        {"Empty User ID", "https://example.com/api/user", "", nil, false},
        {"Invalid User ID", "https://example.com/api/user", "invalid id", nil, true},
    }

    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            got := getURLForQuery(tt.apiURL, tt.userID)
            if (got == nil) != tt.wantErr {
                t.Errorf("getURLForQuery() error = %v, wantErr %v", !tt.wantErr, tt.wantErr)
                return
            }
            if !tt.wantErr && *got != *tt.want {
                t.Errorf("getURLForQuery() = %v, want %v", got, tt.want)
            }
        })
    }
}

func main() {
    fmt.Println(getURLForQuery("https://example.com/api/user", "aBc123")) // Should print the URL
    fmt.Println(getURLForQuery("https://example.com/api/user", ""))       // Should print nil
}

