func getURLForQuery(apiURL, userID string) *string {
    // Check if userID is empty or contains invalid characters
    if userID == "" || !isValidUserID(userID) {
        return nil
    }
    url := apiURL + "/" + userID
    return &url
}

// Helper function to validate userID format
func isValidUserID(id string) bool {
    for _, c := range id {
        if !isAlphanumeric(c) && c != "-" && c != "_" {
            return false
        }
    }
    return true
}

// Helper function to check if a character is alphanumeric or allowed special character
func isAlphanumeric(c rune) bool {
    return ('a' <= c && c <= 'z') ||
           ('A' <= c && c <= 'Z') ||
           ('0' <= c && c <= '9')
}
